const raw = $json.stdout ?? $json.data ?? '';
let rows;
try { rows = JSON.parse(raw); } catch (e) { throw new Error('Python generator must print a JSON array to stdout. Received: ' + String(raw).slice(0,300)); }
if (!Array.isArray(rows)) throw new Error('Python generator output must be a JSON array.');
return rows.map(row => ({ json: row }));

// Basic normalization: trim strings, convert empty strings to null, and remove exact duplicate rows.
const seen = new Set();
const output = [];
for (const item of $input.all()) {
  const row = {};
  for (const [key, value] of Object.entries(item.json ?? {})) {
    row[key] = typeof value === 'string' ? (value.trim() === '' ? null : value.trim()) : value;
  }
  const key = JSON.stringify(row);
  if (!seen.has(key)) { seen.add(key); output.push({json: row}); }
}
return output;

// Lightweight EDA summary from incoming records.
const rows = $input.all().map(x => x.json);
const columns = [...new Set(rows.flatMap(r => Object.keys(r)))];
const summary = { rowCount: rows.length, columns, fields: {} };
for (const col of columns) {
  const vals = rows.map(r => r[col]).filter(v => v !== null && v !== undefined && v !== '');
  const nums = vals.map(Number).filter(Number.isFinite);
  summary.fields[col] = { nonNullCount: vals.length, nullCount: rows.length - vals.length, distinctCount: new Set(vals.map(String)).size };
  if (nums.length) summary.fields[col].numeric = { min: Math.min(...nums), max: Math.max(...nums), mean: nums.reduce((a,b)=>a+b,0)/nums.length };
}
return [{json: {dataset: rows, exploration: summary}}];
